.tilt-card {
  width: 240px; height: 350px;
  background: linear-gradient(135deg, #2b1d3d, #1a0a2a);
  border-radius: 20px; border: 1px solid rgba(168,85,247,0.3);
  transform-style: preserve-3d; transition: transform 0.1s;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  color: #fff; box-shadow: 0 20px 40px rgba(0,0,0,0.5); font-family: sans-serif;
  cursor: pointer;
}
.tilt-content {
  transform: translateZ(50px);
  text-align: center;
}
.tilt-card:hover { box-shadow: 0 30px 60px rgba(168,85,247,0.4); }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;perspective:1000px;background:transparent;';

const card = document.createElement('div');
card.className = 'tilt-card';

const content = document.createElement('div');
content.className = 'tilt-content';
content.innerHTML = '<h2 style="margin:0;color:#00ffcc;">PRO PLAN</h2><h1 style="margin:10px 0;">$49</h1><p style="color:#aaa;font-size:14px;">Per Month</p>';
card.appendChild(content);
c.appendChild(card);

card.addEventListener('pointermove', (e) => {
  const rect = card.getBoundingClientRect();
  const x = e.clientX - rect.left - rect.width / 2;
  const y = e.clientY - rect.top - rect.height / 2;
  card.style.transform = `rotateX(${-y * 0.15}deg) rotateY(${x * 0.15}deg)`;
});
card.addEventListener('pointerleave', () => {
  card.style.transition = 'transform 0.5s ease';
  card.style.transform = `rotateX(0deg) rotateY(0deg)`;
  setTimeout(() => card.style.transition = 'transform 0.1s', 500);
});
